files.content:
.palette {
  width: 100%;
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: var(--radius-panel);
  background: var(--surface);
  box-shadow: 0 18px 44px color-mix(in srgb, var(--foreground) 10%, transparent);
  transform-origin: top center;
}

.searchRow {
  position: relative;
  display: flex;
  min-height: 54px;
  align-items: center;
  gap: 10px;
  padding: 8px 14px;
  border-bottom: 1px solid var(--border-subtle);
  transition: background var(--duration-fast) var(--ease-standard);
}

.searchRow:focus-within { background: var(--surface-muted); }
.searchIcon, .itemIcon { display: grid; flex: none; place-items: center; color: var(--text-muted); }
.searchIcon { width: 22px; height: 22px; }
.searchRow input { min-width: 0; flex: 1; border: 0; outline: 0; background: transparent; color: var(--foreground); font: inherit; font-size: var(--text-sm); }
.searchRow input::placeholder { color: var(--text-muted); }
.searchRow input:focus-visible { outline: none; }

.commandKey, .shortcut, .hint kbd {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: none;
  border: 1px solid var(--border);
  border-radius: 7px;
  background: var(--surface-muted);
  color: var(--text-muted);
  font-family: inherit;
  font-size: 10px;
  font-weight: 500;
  line-height: 1;
}

.commandKey { min-width: 38px; height: 24px; padding: 0 6px; }
.clearButton { display: grid; width: 24px; height: 24px; flex: none; place-items: center; border: 0; border-radius: 7px; background: transparent; color: var(--text-muted); cursor: pointer; transition: color var(--duration-fast) var(--ease-standard), background-color var(--duration-fast) var(--ease-standard); }
@media (hover: hover) and (pointer: fine) { .clearButton:hover, .closeButton:hover { background: var(--surface); color: var(--foreground); } }
.clearButton:active, .closeButton:active { background: var(--surface); color: var(--foreground); }
.clearButton:focus-visible { outline: 2px solid var(--focus-ring); outline-offset: 2px; }
.closeButton { display: grid; min-width: 27px; height: 22px; place-items: center; border: 1px solid var(--border-subtle); border-radius: 6px; background: transparent; color: var(--text-muted); font: inherit; font-size: 10px; cursor: pointer; transition: color var(--duration-fast) var(--ease-standard), background-color var(--duration-fast) var(--ease-standard); }
.closeButton:focus-visible { outline: 2px solid var(--focus-ring); outline-offset: 2px; }

/* The frame animates to the list height; the list keeps its own scroll. */
.resultsFrame { overflow: hidden; }
.results { position: relative; max-height: 342px; overflow: auto; padding: 6px 8px; }
.highlight { position: absolute; top: 0; right: 8px; left: 8px; border: 1px solid color-mix(in srgb, var(--accent) 42%, var(--border)); border-radius: 10px; background: var(--accent-subtle); opacity: 0; pointer-events: none; }
/* Groups are positioned so a row that pops out of the flow is placed against the same box it was measured in, even mid-glide. */
.group { position: relative; }
.group + .group { margin-top: 4px; padding-top: 4px; border-top: 1px solid var(--border-subtle); }
.groupHeading { display: block; padding: 5px 8px 3px; color: var(--text-muted); font-size: 10px; font-weight: 500; letter-spacing: .02em; }

.result { position: relative; display: flex; width: 100%; min-height: 40px; align-items: center; gap: 9px; border: 1px solid transparent; border-radius: 10px; padding: 5px 8px; background: transparent; color: var(--foreground); text-align: left; cursor: pointer; }
/* The active row is drawn by the shared highlight; the row itself only tints its icon and arrow. */
.itemIcon { transition: color var(--duration-fast) var(--ease-standard); }
.activeResult .itemIcon, .activeResult .resultArrow { color: var(--accent-strong); }
.result:focus-visible { outline: 2px solid var(--focus-ring); outline-offset: -2px; }
.itemIcon { width: 20px; height: 20px; }
.resultCopy { min-width: 0; flex: 1; }
.resultCopy strong, .resultCopy small { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.resultCopy strong { font-size: var(--text-sm); font-weight: 500; }
.resultCopy small { margin-top: 2px; color: var(--text-muted); font-size: var(--text-xs); }
.shortcut { min-width: 22px; height: 21px; padding: 0 5px; }
.resultArrow { flex: none; color: var(--text-muted); opacity: .35; transition: opacity var(--duration-fast) var(--ease-standard), color var(--duration-fast) var(--ease-standard), transform var(--duration-spring) var(--ease-spring); }
.activeResult .resultArrow { opacity: .8; transform: translateX(2px); }

.empty { display: grid; justify-items: center; gap: 4px; padding: 26px 12px 28px; text-align: center; }
.empty > span { display: grid; width: 32px; height: 32px; place-items: center; margin-bottom: 5px; color: var(--text-muted); }
.empty strong { font-size: var(--text-sm); font-weight: 500; }
.empty small { color: var(--text-muted); font-size: var(--text-xs); }
.hint { position: relative; display: flex; flex-wrap: wrap; gap: 10px; padding: 8px 14px 10px; border-top: 1px solid var(--border-subtle); color: var(--text-muted); font-size: 10px; }
.hint span { display: inline-flex; align-items: center; gap: 4px; }
.hint kbd { min-width: 18px; height: 18px; padding: 0 4px; }
.visuallyHidden { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }

@media (max-width: 480px) {
  .searchRow { gap: 8px; padding: 8px 11px; }
  .results { padding: 6px; }
  .highlight { right: 6px; left: 6px; }
  .result { gap: 8px; }
  .shortcut, .commandKey { display: none; }
  .hint { gap: 7px; padding: 8px 11px 9px; }
}

@media (max-width: 340px) {
  .hint span:last-child { display: none; }
  .result { padding-inline: 6px; }
}

@media (prefers-reduced-motion: reduce) {
  .searchRow, .itemIcon, .resultArrow, .clearButton, .closeButton { transition: none; }
  .activeResult .resultArrow { transform: none; }
}
